package com.codepilot1c.core.edt.compare;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.nio.file.*;
public class MergeCheckpointStoreTest {
 @Test public void semanticKeysNeverReuseBmIds(){var a=new HashMap<String,Object>(Map.of("node_id","1","path","Module.Method","path_resolved",true,"kind","BslModuleSectionComparisonNode","main_name","Method"));var b=new HashMap<>(a);b.put("node_id","999");assertEquals(MergeCheckpointStore.nodeKey(a),MergeCheckpointStore.nodeKey(b));b.put("path","Other.Method");assertNotEquals(MergeCheckpointStore.nodeKey(a),MergeCheckpointStore.nodeKey(b));}
 @Test public void unresolvedPathsAreNeverGuessed(){assertThrows(IllegalArgumentException.class,()->MergeCheckpointStore.nodeKey(Map.of("path_resolved",false,"path","FT:unknown#1")));}
 @Test public void unresolvedCollectionElementUsesExplicitFqn(){var a=new HashMap<String,Object>(Map.of("path_resolved",false,"kind","TopMdObjectCollectionElementComparisonNode","path","CE:unknown#1","main_fqn","CommonTemplate.Sheet"));var b=new HashMap<>(a);b.put("path","CE:unknown#999");assertEquals(MergeCheckpointStore.nodeKey(a),MergeCheckpointStore.nodeKey(b));}
 @Test public void savedPlanSurvivesStoreRecreationAndChecksumProtectsRestore()throws Exception{Path dir=Files.createTempDirectory("checkpoint-test-");try{var s=new MergeCheckpointStore(dir);var doc=Map.<String,Object>of("main_project","Main","other_project","Other","node_count",1,"nodes",List.of(Map.of("key","x","rule","CUSTOM_MERGE","custom_result","manual result")),"source_guard",Map.of("MAIN","hash"));var saved=s.save(doc);String id=(String)saved.get("checkpoint_id"),hash=(String)saved.get("checkpoint_sha256");assertEquals(doc.get("nodes"),new MergeCheckpointStore(dir).load(id,hash).get("nodes"));assertThrows(IllegalArgumentException.class,()->s.load("../../other",hash));Files.writeString(dir.resolve(id+".json"),"{}");assertThrows(IllegalStateException.class,()->s.load(id,hash));}finally{try(var files=Files.list(dir)){for(var p:files.toList())Files.delete(p);}Files.delete(dir);}}
 @Test public void repeatedPropertiesAreQualifiedBySemanticParents(){var root=new HashMap<String,Object>(Map.of("node_id","0","path","RT","kind","Root","path_resolved",true));var a=new HashMap<String,Object>(Map.of("node_id","1","parent_id","0","path","A","kind","Object","path_resolved",true));var b=new HashMap<String,Object>(Map.of("node_id","2","parent_id","0","path","B","kind","Object","path_resolved",true));var x=new HashMap<String,Object>(Map.of("node_id","3","parent_id","1","path","FT:uuid","kind","Property","path_resolved",true));var y=new HashMap<String,Object>(Map.of("node_id","4","parent_id","2","path","FT:uuid","kind","Property","path_resolved",true));assertEquals(5,MergeCheckpointStore.index(List.of(root,a,b,x,y)).size());assertNotEquals(MergeCheckpointStore.nodeKey(x),MergeCheckpointStore.nodeKey(y));}
 @org.junit.Test public void explicitOrderNeverSilentlyDisappears(){assertThrows(IllegalArgumentException.class,()->MergeCheckpointStore.nodeKey(Map.of("path_resolved",true,"path","FT:items","order_set_by_user",true)));}
}
